```js
const TAU = Math.PI * 2;
const GRAV = 9.81;

// direction (unit), amplitude, wavelength L, speed multiplier, phase
const WAVE_DEFS = [
  { dir: [0.14, 0.99], amp: 0.85, len: 40.0, speed: 1.00, phase: 0.0 },
  { dir: [0.62, 0.78], amp: 0.42, len: 21.0, speed: 1.12, phase: 1.7 },
  { dir: [-0.72, 0.69], amp: 0.24, len: 13.0, speed: 1.28, phase: 3.1 },
  { dir: [0.35, 0.94], amp: 0.13, len: 8.0, speed: 1.45, phase: 4.4 },
  { dir: [0.86, 0.51], amp: 0.07, len: 5.5, speed: 1.7, phase: 5.9 },
];

export const WAVES = WAVE_DEFS.map(w => {
  const l = Math.hypot(w.dir[0], w.dir[1]);
  const dx = w.dir[0]/l, dz = w.dir[1]/l;
  const k = TAU / w.len;
  const omega = Math.sqrt(GRAV * k) * w.speed;
  return { kx: dx*k, kz: dz*k, amp: w.amp, phase: w.phase, omega };
});

