// Shared colour palette for the whole scene.
// Colours are authored as sRGB hex strings; three.js converts them to the
// linear working space for us (ColorManagement is enabled by default).

export const PALETTE = {
  // sun / sky
  sun: '#ffd8a0',
  skyTop: '#12508f',
  skyMid: '#6aa9d4',
  skyHorizon: '#f8d6a6',
  haze: '#f0cba4',
  cloud: '#ffffff',
  cloudShade: '#b9a794',

  // ocean
  deep: '#0a3648',
  shallow: '#1f7f95',
  sss: '#7fe3d0',
  foam: '#fdfdfd',

  // landscape
  island: '#2c5a52',
  gull: '#39465a',

  // pelican
  body: '#f8f5ee',
  wing: '#ece7dc',
  wingTip: '#2b3340',
  beak: '#f0a63c',
  pouch: '#e3813a',
  foot: '#e79a3c',
  bandana: '#d9484c',
  eye: '#20242c',

  // board
  deck: '#f7efdd',
  stringer: '#d9484c',
  pinstripe: '#e8c46a',
  fin: '#d9484c',
};

// Sun direction (points *from* the scene *towards* the sun).
export const SUN_DIR = { x: 0.46, y: 0.17, z: 0.87 };

export const FOG_DENSITY = 0.00068;

// The ocean swell.
//
// One single source of truth: WAVES is precomputed here and used both by the
// CPU (to float the pelican + board) and to generate the GLSL that displaces
// the water mesh, so what you see is exactly what the surfer rides.

const TAU = Math.PI * 2;
const G = 9.81;

// dir: unit-ish direction the swell travels towards.
// amp: wave height (metres), len: wavelength, speed: speed multiplier, phase.
const DEFS = [
  { dir: [0.14, 0.99], amp: 0.86, len: 40.0, speed: 1.0, phase: 0.0 },
  { dir: [0.62, 0.78], amp: 0.44, len: 21.0, speed: 1.12, phase: 1.7 },
  { dir: [-0.72, 0.69], amp: 0.24, len: 13.0, speed: 1.28, phase: 3.1 },
  { dir: [0.35, 0.94], amp: 0.13, len: 8.0, speed: 1.45, phase: 4.4 },
  { dir: [0.86, 0.51], amp: 0.07, len: 5.5, speed: 1.7, phase: 5.9 },
];

export const WAVES = DEFS.map((w) => {
  const l = Math.hypot(w.dir[0], w.dir[1]);
  const dx = w.dir[0] / l;
  const dz = w.dir[1] / l;
  const k = TAU / w.len;
  return {
    kx: dx * k,
    kz: dz * k,
    amp: w.amp,
    phase: w.phase,
    omega: Math.sqrt(G * k) * w.speed,
  };
});

/** Height of the water surface at (x, z) and time t. */
export function waveHeight(x, z, t) {
  let h = 0;
  for (let i = 0; i < WAVES.length; i++) {
    const w = WAVES[i];
    h += w.amp * Math.sin(w.kx * x + w.kz * z + w.phase + w.omega * t);
  }
  return h;
}

// Finite differences are used on both sides so the board and the mesh agree.
const EPS = 0.5;

/** Surface normal at (x, z), written into `target`. */
export function waveNormal(x, z, t, target) {
  const hx = (waveHeight(x + EPS, z, t) - waveHeight(x - EPS, z, t)) / (2 * EPS);
  const hz = (waveHeight(x, z + EPS, t) - waveHeight(x, z - EPS, t)) / (2 * EPS);
  return target.set(-hx, 1, -hz).normalize();
}

const f = (v) => {
  const s = v.toFixed(6);
  return s === '-0.000000' ? '0.0' : s;
};

/** GLSL that mirrors waveHeight() exactly. */
export const WAVE_GLSL = `
float waveAt( vec2 p, float t ) {
  float h = 0.0;
${WAVES.map(
  (w) =>
    `  h += ${f(w.amp)} * sin( p.x * ${f(w.kx)} + p.z * ${f(w.kz)} + ${f(
      w.phase,
    )} + t * ${f(w.omega)} );`,
).join('\n')}
  return h;
}
`;

// The ocean: an endless "projected" polar grid that follows the surfer, so the
// mesh stays dense where the camera is and stretches out to the horizon.
// Displacement happens in the vertex shader; normals, foam and sun glitter are
// evaluated per pixel from the same wave function the surfer rides on.

import * as THREE from 'three';
import { WAVE_GLSL } from './waves.js';
import { PALETTE } from './palette.js';

const NEAR_STEP = 0.5; // spacing of the innermost rings
const NEAR_RINGS = 80; // ... up to r = 40
const RINGS = 240; // total ring count
const SEGMENTS = 192; // quads around the circle
const OUTER_RADIUS = 6000;

function buildWaterGeometry() {
  const positions = [];
  const uvs = [];
  const normals = [];
  const indices = [];

  const radii = [];
  for (let i = 1; i <= NEAR_RINGS; i++) radii.push(i * NEAR_STEP);
  const growth = Math.pow(
    OUTER_RADIUS / (NEAR_RINGS * NEAR_STEP),
    1 / (RINGS - NEAR_RINGS),
  );
  let r = NEAR_RINGS * NEAR_STEP;
  for (let i = NEAR_RINGS; i < RINGS; i++) {
    r *= growth;
    radii.push(r);
  }

  // centre vertex
  positions.push(0, 0, 0);
  normals.push(0, 1, 0);
  uvs.push(0.5, 0.5);

  const ringBase = [];
  let next = 1;
  for (let i = 0; i < radii.length; i++) {
    ringBase.push(next);
    const rad = radii[i];
    for (let j = 0; j < SEGMENTS; j++) {
      const a = (j / SEGMENTS) * Math.PI * 2;
      positions.push(Math.cos(a) * rad, 0, Math.sin(a) * rad);
      normals.push(0, 1, 0);
      uvs.push(0.5 + Math.cos(a) * 0.5, 0.5 + Math.sin(a) * 0.5);
    }
    next += SEGMENTS;
  }

  const quads = SEGMENTS;
  // fan from the single centre vertex
  for (let j = 0; j < quads; j++) {
    indices.push(0, ringBase[0] + ((j + 1) % quads), ringBase[0] + j);
  }
  for (let i = 0; i < ringBase.length - 1; i++) {
    const a = ringBase[i];
    const b = ringBase[i + 1];
    for (let j = 0; j < quads; j++) {
      const j2 = (j + 1) % quads;
      indices.push(a + j, a + j2, b + j2);
      indices.push(a + j, b + j2, b + j);
    }
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  geo.computeBoundingSphere();
  return geo;
}

const vertexShader = /* glsl */ `
uniform float uTime;
varying vec3 vWorld;

${WAVE_GLSL}

void main() {
  vec4 wp = modelMatrix * vec4( position, 1.0 );
  wp.y += waveAt( wp.xz, uTime );
  vWorld = wp.xyz;
  gl_Position = projectionMatrix * viewMatrix * wp;
}
`;

const fragmentShader = /* glsl */ `
precision highp float;

uniform float uTime;
uniform vec3 uSunDir;
uniform vec3 uSunColor;
uniform vec3 uSkyTop;
uniform vec3 uHorizon;
uniform vec3 uDeep;
uniform vec3 uShallow;
uniform vec3 uFoam;
uniform vec3 uFogColor;
uniform float uFogDensity;
uniform vec2 uRider;
uniform float uSparkle;

varying vec3 vWorld;

${WAVE_GLSL}

float hash21( vec2 p ) {
  p = fract( p * vec2( 123.34, 456.21 ) );
  p += dot( p, p + 45.32 );
  return fract( p.x * p.y );
}

float vnoise( vec2 p ) {
  vec2 i = floor( p );
  vec2 f = fract( p );
  f = f * f * ( 3.0 - 2.0 * f );
  const float o = 110.0;
  float a = hash21( i );
  float b = hash21( i + vec2( o, 0.0 ) );
  float c = hash21( i + vec2( 0.0, o ) );
  float d = hash21( i + vec2( o, o ) );
  return mix( mix( a, b, f.x ), mix( c, d, f.x ), f.y );
}

float fbm( vec2 p ) {
  float v = 0.0;
  float a = 0.5;
  for ( int i = 0; i < 4; i ++ ) {
    v += a * vnoise( p );
    p *= 2.03;
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 p = vWorld.xz;
  float t = uTime;

  float h = waveAt( p, t );

  // per-pixel normal by finite differences (same eps as the CPU version)
  float e = 0.5;
  float hx = ( waveAt( p + vec2( e, 0.0 ), t ) - waveAt( p - vec2( e, 0.0 ), t ) ) / ( 2.0 * e );
  float hz = ( waveAt( p + vec2( 0.0, e ), t ) - waveAt( p - vec2( 0.0, e ), t ) ) / ( 2.0 * e );
  vec3 n = normalize( vec3( -hx, 1.0, -hz ) );

  vec3 view = normalize( cameraPosition - vWorld );
  float ndv = clamp( dot( n, view ), 0.0, 1.0 );

  // --- body colour: deep in the troughs, bright and translucent on the faces
  float hn = smoothstep( -0.95, 1.0, h );
  vec3 col = mix( uDeep, uShallow, hn );

  // light bleeding through the wave faces
  float sss = pow( clamp( h, 0.0, 1.4 ) / 1.4, 2.0 ) * pow( ndv, 1.5 );
  col += uSunColor * sss * 0.30;

  // --- sky reflection (fresnel)
  float fres = 0.025 + 0.975 * pow( 1.0 - ndv, 5.0 );
  vec3 rdir = reflect( -view, n );
  rdir.y = abs( rdir.y );
  vec3 sky = mix( uHorizon, uSkyTop, smoothstep( 0.0, 0.45, rdir.y ) );
  col = mix( col, sky, clamp( fres, 0.0, 1.0 ) );

  // --- sun glitter
  vec3 hv = normalize( uSunDir + view );
  float nh = max( dot( n, hv ), 0.0 );
  float broad = pow( nh, 22.0 ) * 0.30;
  float sharp = pow( nh, 420.0 ) * 1.35 * uSparkle;
  col += uSunColor * ( broad + sharp );

  // --- whitecaps on the steep, high parts of the swell
  float slope = 1.0 - n.y;
  float crest = smoothstep( 0.62, 1.28, h );
  float steep = smoothstep( 0.035, 0.15, slope );
  float mottle = fbm( p * 0.42 + vec2( t * 0.25, t * 0.05 ) );
  float foam = crest * steep * smoothstep( 0.35, 0.72, mottle );

  // --- disturbed water around the board
  vec2 d = p - uRider;
  float wr = length( d );
  float wake = smoothstep( 6.0, 0.0, wr ) * ( 0.30 + 0.45 * smoothstep( 0.4, 0.9, h ) );

  col = mix( col, uFoam, clamp( foam * 0.95 + wake * 0.5, 0.0, 1.0 ) );

  // --- haze
  float dist = length( cameraPosition - vWorld );
  float fk = uFogDensity * dist;
  float f = 1.0 - exp( -fk * fk );
  col = mix( col, uFogColor, clamp( f, 0.0, 1.0 ) );

  gl_FragColor = vec4( col, 1.0 );
  gl_FragColor = linearToOutputTexel( gl_FragColor );
}
`;

const lin = (hex) => new THREE.Color(hex).convertSRGBToLinear();

export function createOcean(scene) {
  const geometry = buildWaterGeometry();

  const uniforms = {
    uTime: { value: 0 },
    uSunDir: { value: new THREE.Vector3(...Object.values(PALETTE ? SUN : {})) },
    uSunColor: { value: lin(PALETTE.sun) },
    uSkyTop: { value: lin(PALETTE.skyTop) },
    uHorizon: { value: lin(PALETTE.skyHorizon) },
    uDeep: { value: lin(PALETTE.deep) },
    uShallow: { value: lin(PALETTE.shallow) },
    uFoam: { value: lin(PALETTE.foam) },
    uFogColor: { value: lin(PALETTE.haze) },
    uFogDensity: { value: 0.00068 },
    uRider: { value: new THREE.Vector2() },
    uSparkle: { value: 1 },
  };

  const material = new THREE.ShaderMaterial({
    uniforms,
    vertexShader,
    fragmentShader,
    side: THREE.DoubleSide,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.renderOrder = 1;
  scene.add(mesh);

  return { mesh, uniforms };
}

