// The star of the show: a pelican on a surfboard, procedurally modelled from
// three.js primitives and extruded shapes. No external assets.

import * as THREE from 'three';
import { PALETTE } from './palette.js';
import { waveHeight, waveNormal } from './waves.js';

// ---------------------------------------------------------------------------
// small helpers
// ---------------------------------------------------------------------------

const std = (color, opts = {}) =>
  new THREE.MeshStandardMaterial({
    color: new THREE.Color(color),
    roughness: 0.82,
    metalness: 0.0,
    ...opts,
  });

function extrude(shape, { depth, bevel = 0.05, bevelSize = 0.035, curveSegments = 14 }) {
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: true,
    bevelThickness: bevel,
    bevelSize,
    bevelSegments: 4,
    curveSegments,
    steps: 1,
  });
  return geo;
}

function mesh(geometry, material, name) {
  const m = new THREE.Mesh(geometry, material);
  m.name = name;
  m.castShadow = false;
  m.receiveShadow = false;
  return m;
}

const mat = (name) => std(PALETTE[name]);

// ---------------------------------------------------------------------------
// surfboard
// ---------------------------------------------------------------------------

function buildBoard() {
  const group = new THREE.Group();
  group.name = 'board';

  // plan-view outline: length along local x, width along local y, then rotated
  // so the nose points at +z.
  const s = new THREE.Shape();
  s.moveTo(0, 2.45);
  s.bezierCurveTo(0.42, 1.65, 0.5, 0.72, 0.48, 0.0);
  s.bezierCurveTo(0.46, -0.62, 0.4, -1.3, 0.0, -1.6);
  s.bezierCurveTo(-0.4, -1.3, -0.46, -0.62, -0.48, 0.0);
  s.bezierCurveTo(-0.5, 0.72, -0.42, 1.65, 0.0, 2.45);

  const geo = extrude(s, { depth: 0.3, bevel: 0.09, bevelSize: 0.06, curveSegments: 24 });
  geo.rotateX(Math.PI / 2);
  geo.rotateY(-Math.PI / 2);
  geo.computeBoundingBox();
  const bb = geo.boundingBox;
  geo.translate(0, -bb.min.y, -(bb.min.z + bb.max.z) / 2);

  const deck = mesh(geo, std(PALETTE.deck, { roughness: 0.6 }), 'deck');
  group.add(deck);

  // red stringer down the middle + pinstripes
  const stringer = mesh(
    new THREE.BoxGeometry(0.075, 0.02, 4.1),
    std(PALETTE.stringer, { roughness: 0.5 }),
    'stringer',
  );
  stringer.position.set(0, 0.31, 0.05);
  group.add(stringer);

  for (const x of [-0.2, 0.2]) {
    const pin = mesh(
      new THREE.BoxGeometry(0.028, 0.018, 3.5),
      std(PALETTE.pinstripe, { roughness: 0.45, metalness: 0.15 }),
      'pinstripe',
    );
    pin.position.set(x, 0.306, 0.1);
    group.add(pin);
  }

  // nose pad
  const pad = mesh(
    new THREE.BoxGeometry(0.16, 0.014, 0.7),
    std(PALETTE.stringer, { roughness: 0.7 }),
    'nosepad',
  );
  pad.position.set(0, 0.305, 1.35);
  group.add(pad);

  // tail fin
  const fin = mesh(new THREE.ConeGeometry(0.24, 0.6, 4), std(PALETTE.fin, { roughness: 0.6 }), 'fin');
  fin.scale.set(0.35, 1, 1.5);
  fin.rotation.x = -0.42;
  fin.position.set(0, -0.1, -1.45);
  group.add(fin);

  return group;
}

// ---------------------------------------------------------------------------
// pelican
// ---------------------------------------------------------------------------

function buildWing(sign) {
  // outline in (span, chord): x = span outwards, y = forwards
  const s = new THREE.Shape();
  s.moveTo(0, -0.3);
  s.quadraticCurveTo(0.45, -0.32, 0.86, -0.11);
  s.quadraticCurveTo(0.99, 0.02, 0.9, 0.13);
  s.quadraticCurveTo(0.5, 0.32, 0.0, 0.24);
  s.lineTo(0, -0.3);

  const geo = extrude(s, { depth: 0.07, bevel: 0.05, bevelSize: 0.03, curveSegments: 20 });
  geo.rotateX(Math.PI / 2); // span -> x, chord -> z, thickness -> y

  if (sign < 0) {
    const pos = geo.attributes.position;
    for (let i = 0; i < pos.count; i++) pos.setX(i, -pos.getX(i));
    pos.needsUpdate = true;
    geo.computeVertexNormals();
  }

  // dark wingtips via vertex colours
  const count = geo.attributes.position.count;
  const colors = new Float32Array(count * 3);
  const light = new THREE.Color(PALETTE.wing);
  const dark = new THREE.Color(PALETTE.wingTip);
  const c = new THREE.Color();
  const v = new THREE.Vector3();
  for (let i = 0; i < count; i++) {
    v.fromBufferAttribute(geo.attributes.position, i);
    const k = 1 - THREE.MathUtils.smoothstep(Math.abs(v.x), 0.62, 0.74);
    c.copy(dark).lerp(light, k);
    colors[i * 3] = c.r;
    colors[i * 3 + 1] = c.g;
    colors[i * 3 + 2] = c.b;
  }
  geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));

  const material = std('#ffffff', { vertexColors: true, roughness: 0.88 });
  return mesh(geo, material, 'wing');
}

function buildTail() {
  const s = new THREE.Shape();
  s.moveTo(0, 0.05);
  s.bezierCurveTo(0.2, 0.2, 0.46, 0.16, 0.56, 0.0);
  s.bezierCurveTo(0.5, -0.12, 0.3, -0.2, 0.0, -0.24);
  s.lineTo(0, 0.05);
  const geo = extrude(s, { depth: 0.06, bevel: 0.04, bevelSize: 0.025, curveSegments: 16 });
  geo.rotateX(Math.PI / 2);
  // outline points forward; flip so the fan points backwards
  geo.scale(1, 1, -1);
  geo.computeVertexNormals();
  const material = std(PALETTE.body, { vertexColors: false, roughness: 0.85 });
  return mesh(geo, material, 'tail');
}

function buildPelican() {
  const g = new THREE.Group();
  g.name = 'pelican';

  // --- torso ---------------------------------------------------------------
  const bodyGeo = new THREE.SphereGeometry(0.42, 28, 20);
  bodyGeo.scale(0.86, 1.0, 1.34);
  const body = mesh(bodyGeo, std(PALETTE.body, { roughness: 0.9 }), 'body');
  body.position.set(0, 0.66, -0.08);
  g.add(body);

  // chest / belly shading blob
  const belly = mesh(new THREE.SphereGeometry(0.4, 20, 14), std(PALETTE.body, { roughness: 1.0 }));
  belly.scale.set(0.82, 0.95, 1.2);
  belly.position.set(0, 0.6, -0.02);
  g.add(belly);

  const tail = buildTail();
  tail.position.set(0, 0.66, -0.62);
  tail.rotation.x = -0.28;
  g.add(tail);

  // --- neck ----------------------------------------------------------------
  const curve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 0.86, 0.02),
    new THREE.Vector3(0.02, 1.12, 0.12),
    new THREE.Vector3(0.0, 1.36, 0.24),
    new THREE.Vector3(0.0, 1.5, 0.3),
  ]);
  const neckGeo = new THREE.TubeGeometry(curve, 24, 0.16, 14, false);
  // taper the tube
  const np = neckGeo.attributes.position;
  for (let i = 0; i < np.count; i++) {
    // nothing to do here: taper is approximated by the second tube below
  }
  const neck = mesh(neckGeo, std(PALETTE.body, { roughness: 0.9 }), 'neck');
  g.add(neck);

  // bandana collar around the neck
  const u = 0.16;
  const bp = curve.getPointAt(u);
  const bt = curve.getTangentAt(u);
  const collar = mesh(new THREE.TorusGeometry(0.165, 0.032, 8, 22), std(PALETTE.bandana, { roughness: 0.85 }), 'collar');
  collar.position.copy(bp);
  collar.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), bt.clone().normalize());
  g.add(collar);
  const knot = mesh(new THREE.BoxGeometry(0.1, 0.07, 0.05), std(PALETTE.bandana), 'knot');
  knot.position.copy(bp).add(new THREE.Vector3(0.16, -0.02, 0).applyQuaternion(collar.quaternion));
  g.add(knot);

  // --- head ----------------------------------------------------------------
  const head = new THREE.Group();
  head.name = 'head';
  head.position.set(0, 1.52, 0.32);
  g.add(head);

  const skullGeo = new THREE.SphereGeometry(0.2, 24, 18);
  skullGeo.scale(0.95, 1.0, 1.08);
  const skull = mesh(skullGeo, std(PALETTE.body, { roughness: 0.85 }), 'skull');
  head.add(skull);

  // little crest feathers
  const crest = mesh(new THREE.ConeGeometry(0.055, 0.16, 6), std(PALETTE.body), 'crest');
  crest.position.set(0, 0.17, -0.04);
  crest.rotation.x = -0.5;
  head.add(crest);

  // upper mandible: thin curved blade, built as a side profile
  const bs = new THREE.Shape();
  bs.moveTo(-0.04, 0.07);
  bs.quadraticCurveTo(0.5, 0.11, 1.0, 0.07);
  bs.quadraticCurveTo(1.14, 0.05, 1.12, -0.01);
  bs.quadraticCurveTo(0.7, -0.05, -0.04, -0.05);
  bs.lineTo(-0.04, 0.07);
  const beakGeo = extrude(bs, { depth: 0.17, bevel: 0.03, bevelSize: 0.02, curveSegments: 20 });
  beakGeo.rotateY(-Math.PI / 2); // profile length -> +z
  beakGeo.translate(0, 0, -0.08);
  const beak = mesh(beakGeo, std(PALETTE.beak, { roughness: 0.55 }), 'beak');
  head.add(beak);

  // pouch hanging under the mandible
  const pouchGeo = new THREE.SphereGeometry(0.15, 20, 14);
  pouchGeo.scale(1.0, 0.78, 3.6);
  const pouch = mesh(pouchGeo, std(PALETTE.pouch, { roughness: 0.6 }), 'pouch');
  pouch.position.set(0, -0.075, 0.72);
  head.add(pouch);

  // eyes
  for (const x of [-1, 1]) {
    const eye = mesh(new THREE.SphereGeometry(0.038, 12, 10), std(PALETTE.eye, { roughness: 0.35 }), 'eye');
    eye.position.set(0.125 * x, 0.035, 0.11);
    head.add(eye);
    const gleam = mesh(
      new THREE.SphereGeometry(0.013, 8, 8),
      std('#ffffff', { roughness: 0.2, emissive: new THREE.Color('#ffffff'), emissiveIntensity: 0.15 }),
      'gleam',
    );
    gleam.position.set(0.133 * x, 0.05, 0.14);
    head.add(gleam);
  }

  // --- legs + feet ---------------------------------------------------------
  for (const z of [0.5, -0.38]) {
    const leg = mesh(new THREE.CylinderGeometry(0.055, 0.05, 0.3, 10), std(PALETTE.foot, { roughness: 0.8 }), 'leg');
    leg.position.set(0.02, 0.42, z);
    g.add(leg);
    const footGeo = new THREE.SphereGeometry(0.16, 14, 8);
    footGeo.scale(1.35, 0.4, 1.5);
    const foot = mesh(footGeo, std(PALETTE.foot, { roughness: 0.85 }), 'foot');
    foot.position.set(0.02, 0.31, z + 0.04);
    g.add(foot);
  }

  // --- wings ---------------------------------------------------------------
  const wingPivots = [];
  for (const sign of [1, -1]) {
    const pivot = new THREE.Group();
    pivot.name = sign > 0 ? 'wingL' : 'wingR';
    pivot.position.set(0.24 * sign, 0.9, -0.02);
    const wing = buildWing(sign);
    pivot.add(wing);
    g.add(pivot);
    wingPivots.push(pivot);
  }

  return { group: g, head, wingPivots };
}

// ---------------------------------------------------------------------------
// rider: board + pelican riding the swell
// ---------------------------------------------------------------------------

const SPEED = 9.6;

export function createRider(scene) {
  const rider = new THREE.Group();
  rider.name = 'rider';
  scene.add(rider);

  const board = buildBoard();
  rider.add(board);

  const pelican = buildPelican();
  rider.add(pelican.group);
  pelican.group.position.y = 0.31;

  // slight sideways surf stance
  pelican.group.rotation.y = -0.42;

  const state = {
    position: new THREE.Vector3(),
    forward: new THREE.Vector3(0, 0, 1),
    up: new THREE.Vector3(0, 1, 0),
    right: new THREE.Vector3(1, 0, 0),
    speed: 0,
    lean: 0,
    wave: 0,
  };

  const n = new THREE.Vector3();
  const fwd = new THREE.Vector3();
  const right = new THREE.Vector3();
  const up = new THREE.Vector3();
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();

  function update(t) {
    // --- path: a long, lazy carve down the line
    const x = t * SPEED;
    const z = 26 * Math.sin(t * 0.078) + 7 * Math.sin(t * 0.31 + 1.1);
    const dx = SPEED;
    const dz = 26 * 0.078 * Math.cos(t * 0.078) + 7 * 0.31 * Math.cos(t * 0.31 + 1.1);
    const speed = Math.hypot(dx, dz);

    const h = waveHeight(x, z, t);
    waveNormal(x, z, t, n);

    fwd.set(dx, 0, dz).normalize();
    right.crossVectors(n, fwd).normalize();
    up.crossVectors(fwd, right).normalize();
    // build orthonormal basis (forward = local +z, up = local +y)
    m.makeBasis(right, up, fwd);
    q.setFromRotationMatrix(m);

    // --- carving lean: bank into the turns
    const curvature = (26 * 0.078 * 0.078 * -Math.sin(t * 0.078) + 7 * 0.31 * 0.31 * -Math.sin(t * 0.31 + 1.1)) / speed;
    const leanTarget = THREE.MathUtils.clamp(curvature * 6.0, -0.34, 0.34);
    state.lean += (leanTarget - state.lean) * 0.08;

    rider.position.set(x, h + 0.13, z);
    rider.quaternion.copy(q);
    rider.rotateZ(state.lean);

    state.position.copy(rider.position);
    state.forward.copy(fwd);
    state.up.copy(up);
    state.right.copy(right);
    state.speed = speed;
    state.wave = h;

    // --- body language
    const bob = Math.sin(t * 2.1) * 0.02 + Math.sin(t * 3.7 + 1.0) * 0.012;
    pelican.group.position.y = 0.31 + bob;
    pelican.group.rotation.z = -state.lean * 0.55 + Math.sin(t * 1.7) * 0.03;
    pelican.group.rotation.x = -0.04 + Math.sin(t * 2.6) * 0.02;

    // head: looks where it is going, with a lazy sway
    pelican.head.rotation.y = 0.42 + Math.sin(t * 0.53) * 0.28 + Math.sin(t * 1.31) * 0.06;
    pelican.head.rotation.x = Math.sin(t * 0.77) * 0.09 - 0.05;
    pelican.head.rotation.z = -state.lean * 0.2;

    // wings: mostly gliding, with an occasional steady flap
    const flapEnv = 0.55 + 0.45 * Math.sin(t * 0.21 + Math.sin(t * 0.13) * 1.5);
    const flap = Math.sin(t * 4.6) * 0.42 * flapEnv + Math.sin(t * 1.15) * 0.05;
    const sweep = Math.sin(t * 2.3) * 0.12;
    pelican.wingPivots[0].rotation.z = 0.3 + flap;
    pelican.wingPivots[1].rotation.z = -(0.3 + flap);
    pelican.wingPivots[0].rotation.y = -0.26 + sweep;
    pelican.wingPivots[1].rotation.y = 0.26 - sweep;
  }

  update(0);
  return { group: rider, board, state, update };
}

