// Rooster-tail spray thrown up behind the board. A small CPU particle pool
// rendered as additive-ish round sprites.

import * as THREE from 'three';
import { PALETTE } from './palette.js';

const MAX = 420;

const vertexShader = /* glsl */ `
attribute float aSize;
attribute float aAlpha;
varying float vAlpha;
void main() {
  vAlpha = aAlpha;
  vec4 mv = modelViewMatrix * vec4( position, 1.0 );
  gl_PointSize = aSize * 420.0 / max( 0.001, -mv.z );
  gl_Position = projectionMatrix * mv;
}
`;

const fragmentShader = /* glsl */ `
precision highp float;
uniform vec3 uColor;
varying float vAlpha;
void main() {
  vec2 c = gl_PointCoord - 0.5;
  float d = length( c );
  if ( d > 0.5 || vAlpha <= 0.001 ) discard;
  float a = smoothstep( 0.5, 0.08, d ) * vAlpha;
  gl_FragColor = vec4( uColor, a );
  gl_FragColor = linearToOutputTexel( gl_FragColor );
}
`;

const lin = (hex) => new THREE.Color(hex).convertSRGBToLinear();

export function createSpray(scene) {
  const positions = new Float32Array(MAX * 3);
  const sizes = new Float32Array(MAX);
  const alphas = new Float32Array(MAX);
  const vel = new Float32Array(MAX * 3);
  const life = new Float32Array(MAX);
  const span = new Float32Array(MAX);

  for (let i = 0; i < MAX; i++) {
    positions[i * 3 + 1] = -999; // park dead droplets below the world
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geo.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));
  geo.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));

  const material = new THREE.ShaderMaterial({
    uniforms: { uColor: { value: lin(PALETTE.foam) } },
    vertexShader,
    fragmentShader,
    transparent: true,
    depthWrite: false,
  });

  const points = new THREE.Points(geo, material);
  points.frustumCulled = false;
  points.renderOrder = 3;
  scene.add(points);

  let cursor = 0;
  let carry = 0;
  const spawnAt = new THREE.Vector3();
  const dir = new THREE.Vector3();

  function spawn(rider, intensity) {
    const st = rider.state;
    // just behind the tail of the board
    spawnAt.set(0, 0.35, -1.7).applyMatrix4(rider.group.matrixWorld);
    dir.copy(st.forward).multiplyScalar(-1);

    const i = cursor;
    cursor = (cursor + 1) % MAX;
    positions[i * 3] = spawnAt.x + (Math.random() - 0.5) * 0.5;
    positions[i * 3 + 1] = spawnAt.y + Math.random() * 0.25;
    positions[i * 3 + 2] = spawnAt.z + (Math.random() - 0.5) * 0.5;

    const back = 2.5 + Math.random() * 5.0;
    const up = 2.0 + Math.random() * 4.5 * intensity;
    const side = (Math.random() - 0.5) * 3.0;
    vel[i * 3] = dir.x * back + st.right.x * side;
    vel[i * 3 + 1] = up;
    vel[i * 3 + 2] = dir.z * back + st.right.z * side;

    life[i] = 1;
    span[i] = 0.7 + Math.random() * 1.5;
    sizes[i] = 0.07 + Math.random() * 0.2;
    alphas[i] = 1;
  }

  function update(t, dt, rider) {
    const st = rider.state;
    const intensity = Math.min(1, 0.35 + Math.abs(st.wave) * 0.9);

    // emit at a rate that follows the swell
    carry += dt * (34 + intensity * 46);
    let n = Math.floor(carry);
    carry -= n;
    n = Math.min(n, MAX - 1);
    for (let k = 0; k < n; k++) spawn(rider, intensity);

    for (let i = 0; i < MAX; i++) {
      if (life[i] <= 0) continue;
      life[i] -= dt / span[i];
      if (life[i] <= 0) {
        life[i] = 0;
        alphas[i] = 0;
        sizes[i] = 0;
        positions[i * 3 + 1] = -999;
        continue;
      }
      vel[i * 3 + 1] -= 7.5 * dt; // gravity
      positions[i * 3] += vel[i * 3] * dt;
      positions[i * 3 + 1] += vel[i * 3 + 1] * dt;
      positions[i * 3 + 2] += vel[i * 3 + 2] * dt;
      alphas[i] = Math.min(1, life[i] * 3.0) * life[i];
      sizes[i] += dt * 0.35;
    }

    geo.attributes.position.needsUpdate = true;
    geo.attributes.aSize.needsUpdate = true;
    geo.attributes.aAlpha.needsUpdate = true;
  }

  return { points, update };
}

// A small escort of gulls wheeling around the surfer.

import * as THREE from 'three';
import { PALETTE } from './palette.js';

function buildGull() {
  const g = new THREE.Group();

  const bodyGeo = new THREE.ConeGeometry(0.16, 0.95, 7);
  bodyGeo.rotateX(Math.PI / 2); // point towards +z
  g.add(new THREE.Mesh(bodyGeo, gullMat()));

  const headGeo = new THREE.SphereGeometry(0.13, 10, 8);
  const head = new THREE.Mesh(headGeo, gullMat());
  head.position.set(0, 0.06, 0.42);
  g.add(head);

  const beakGeo = new THREE.ConeGeometry(0.045, 0.28, 5);
  beakGeo.rotateX(Math.PI / 2);
  const beak = new THREE.Mesh(beakGeo, gullMat());
  beak.position.set(0, 0.04, 0.66);
  g.add(beak);

  const tail = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.42, 4), gullMat());
  tail.rotation.x = -Math.PI / 2;
  tail.scale.set(0.4, 1, 1.5);
  tail.position.set(0, 0.02, -0.55);
  g.add(tail);

  // wings: two thin blades on pivots
  const wingShape = new THREE.Shape();
  wingShape.moveTo(0, 0);
  wingShape.quadraticCurveTo(0.55, 0.16, 1.15, 0.02);
  wingShape.quadraticCurveTo(0.6, -0.06, 0, -0.05);
  wingShape.lineTo(0, 0);
  const wingGeo = new THREE.ExtrudeGeometry(wingShape, {
    depth: 0.03,
    bevelEnabled: false,
    curveSegments: 10,
    steps: 1,
  });
  wingGeo.rotateX(Math.PI / 2);

  const wings = [];
  for (const sign of [1, -1]) {
    const pivot = new THREE.Group();
    pivot.position.set(0, 0.08, 0.05);
    const geo = sign > 0 ? wingGeo : wingGeo.clone();
    if (sign < 0) mirrorX(geo);
    pivot.add(new THREE.Mesh(geo, gullMat()));
    g.add(pivot);
    wings.push(pivot);
  }

  return { group: g, wings };
}

function mirrorX(geo) {
  const pos = geo.attributes.position;
  const nor = geo.attributes.normal;
  for (let i = 0; i < pos.count; i++) {
    pos.setX(i, -pos.getX(i));
    if (nor) nor.setX(i, -nor.getX(i));
  }
  pos.needsUpdate = true;
  if (nor) nor.needsUpdate = true;
}

let material;
function gullMat() {
  if (!material) {
    material = new THREE.MeshStandardMaterial({
      color: new THREE.Color(PALETTE.gull),
      roughness: 0.9,
      metalness: 0,
      flatShading: true,
      side: THREE.DoubleSide,
    });
  }
  return material;
}

const BIRDS = 5;

export function createFlock(scene) {
  const group = new THREE.Group();
  group.name = 'flock';
  scene.add(group);

  const birds = [];
  for (let i = 0; i < BIRDS; i++) {
    const bird = buildGull();
    group.add(bird.group);
    const rank = Math.floor(i / 2) + 1;
    const side = i % 2 === 0 ? -1 : 1;
    birds.push({
      ...bird,
      radius: 26 + rank * 16,
      offset: side * (rank * 5.5) + (i === 4 ? 0 : side * 1.5),
      lead: i === 4 ? 0 : -rank * 0.55,
      height: i === 4 ? 8.5 : 7.5 + Math.sin(i) * 1.4,
      phase: i * 0.9,
      speed: i === 4 ? 0.052 : 0.05 + rank * 0.004,
    });
  }

  const up = new THREE.Vector3();
  const fwd = new THREE.Vector3();
  const right = new THREE.Vector3();
  const pos = new THREE.Vector3();
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();

  return {
    group,
    update(t, rider) {
      const st = rider.state;
      up.copy(st.up);
      fwd.copy(st.forward);
      right.copy(st.right);

      for (const b of birds) {
        const a = t * b.speed * 6.0 + b.phase;
        const x = Math.cos(a) * b.radius + b.lead * 14.0;
        const z = Math.sin(a) * b.radius * 0.55 + b.offset * 6.0;
        pos
          .copy(right)
          .multiplyScalar(x)
          .addScaledVector(fwd, z)
          .addScaledVector(up, b.height + Math.sin(t * 0.8 + b.phase) * 1.2)
          .add(st.position);

        // face along the circle tangent
        const tx = -Math.sin(a) * b.radius;
        const tz = Math.cos(a) * b.radius * 0.55;
        const tan = right.clone().multiplyScalar(tx).addScaledVector(fwd, tz).normalize();
        const bank = new THREE.Vector3().crossVectors(up, tan).normalize();
        const newUp = new THREE.Vector3().crossVectors(tan, bank).normalize();
        m.makeBasis(bank, newUp, tan);
        q.setFromRotationMatrix(m);
        b.group.position.copy(pos);
        b.group.quaternion.copy(q);

        const flap = Math.sin(t * 7.5 + b.phase * 3.0);
        const idle = -0.15;
        b.wings[0].rotation.z = idle + flap * 0.55;
        b.wings[1].rotation.z = -(idle + flap * 0.55);
      }
    },
  };
}

// Low-poly islands on the horizon, re-cycled as the surfer travels so the sea
// never runs out.

import * as THREE from 'three';
import { PALETTE } from './palette.js';

function hash(n) {
  const s = Math.sin(n * 127.1) * 43758.5453;
  return s - Math.floor(s);
}

function buildIsland(segments = 9) {
  const geo = new THREE.ConeGeometry(1, 1, segments, 4, false);
  const pos = geo.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const y = pos.getY(i);
    const x = pos.getX(i);
    const z = pos.getZ(i);
    if (y < -0.49) continue; // leave the base cap alone
    const k = hash(i);
    const jitter = 1 + (k - 0.5) * 0.34;
    const lift = 1 + (hash(i + 91) - 0.5) * 0.28;
    pos.setX(i, x * jitter);
    pos.setZ(i, z * jitter);
    pos.setY(i, y * lift + (y > 0.4 ? 0.12 * hash(i + 7) : 0));
  }
  pos.needsUpdate = true;
  geo.computeVertexNormals();
  return geo;
}

const ISLANDS = [
  { ox: -1500, oz: -2400, s: 320, h: 130, ry: 0.4, tint: '#2c5a52' },
  { ox: 900, oz: -2000, s: 210, h: 90, ry: 1.9, tint: '#33635a' },
  { ox: 2100, oz: -2600, s: 420, h: 170, ry: 2.7, tint: '#28524b' },
  { ox: -2600, oz: -1500, s: 150, h: 62, ry: 0.9, tint: '#3a6b60' },
  { ox: 300, oz: -2900, s: 260, h: 105, ry: 3.4, tint: '#2a534c' },
  { ox: -600, oz: -3200, s: 520, h: 210, ry: 1.2, tint: '#234a45' },
];

const WRAP = 6000;

export function createIslands(scene) {
  const group = new THREE.Group();
  group.name = 'islands';
  scene.add(group);

  const items = ISLANDS.map((cfg) => {
    const mat = new THREE.MeshStandardMaterial({
      color: new THREE.Color(cfg.tint),
      roughness: 1,
      metalness: 0,
      flatShading: true,
    });
    const m = new THREE.Mesh(buildIsland(9), mat);
    m.scale.set(cfg.s, cfg.h, cfg.s);
    m.position.set(cfg.ox, cfg.h * 0.5 - 8, cfg.oz);
    m.rotation.y = cfg.ry;
    group.add(m);
    return { mesh: m, cfg };
  });

  return {
    group,
    update(rider) {
      for (const it of items) {
        let x = it.cfg.ox;
        // wrap relative to the surfer so islands recycle smoothly
        while (x - rider.state.position.x > WRAP / 2) x -= WRAP;
        while (x - rider.state.position.x < -WRAP / 2) x += WRAP;
        it.mesh.position.x = x;
      }
    },
  };
}

// Soft "contact shadow" that the board throws onto the water. Cheaper (and far
// less moody) than a real shadow map for a transparent ocean shader.

import * as THREE from 'three';
import { PALETTE } from './palette.js';

const vertexShader = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4( position, 1.0 );
}
`;

const fragmentShader = /* glsl */ `
precision highp float;
uniform vec3 uColor;
uniform float uStrength;
varying vec2 vUv;
void main() {
  vec2 c = vUv - 0.5;
  c.x *= 1.9; // shadow is longer than it is wide
  float d = length( c * vec2( 1.0, 1.35 ) );
  float a = smoothstep( 0.5, 0.05, d ) * uStrength;
  gl_FragColor = vec4( uColor, a );
  gl_FragColor = linearToOutputTexel( gl_FragColor );
}
`;

export function createContactShadow(scene) {
  const geo = new THREE.PlaneGeometry(9.5, 5.2);
  geo.rotateX(-Math.PI / 2); // lay flat, facing +y

  const material = new THREE.ShaderMaterial({
    uniforms: {
      uColor: { value: new THREE.Color(PALETTE.deep).convertSRGBToLinear() },
      uStrength: { value: 0.5 },
    },
    vertexShader,
    fragmentShader,
    transparent: true,
    depthWrite: false,
  });

  const mesh = new THREE.Mesh(geo, material);
  mesh.renderOrder = 2;
  mesh.frustumCulled = false;
  scene.add(mesh);

  const up = new THREE.Vector3();
  const fwd = new THREE.Vector3();
  const right = new THREE.Vector3();
  const m = new THREE.Matrix4();
  const q = new THREE.Quaternion();

  return {
    mesh,
    update(rider) {
      const st = rider.state;
      up.copy(st.up);
      fwd.copy(st.forward);
      right.crossVectors(up, fwd).normalize();
      m.makeBasis(right, up, fwd);
      q.setFromRotationMatrix(m);
      mesh.position.copy(st.position);
      mesh.position.y += 0.09;
      mesh.quaternion.copy(q);
      // stronger, tighter shadow when the board sits deep in the face
      material.uniforms.uStrength.value = 0.38 + Math.min(0.4, Math.abs(st.wave) * 0.35);
    },
  };
}

