export const SHOT_TOTAL = SHOTS.reduce((a, s) => a + s.dur, 0);

export function createCameraRig(camera) {
  const pos = new THREE.Vector3();
  const target = new THREE.Vector3();
  const dPos = new THREE.Vector3();
  const dTarget = new THREE.Vector3();
  const up = new THREE.Vector3(0, 1, 0);
  const blended = new THREE.Vector3();
  const hold = { pos: new THREE.Vector3(), target: new THREE.Vector3() };

  let index = 0;
  let shotTime = 0;
  let changed = false;
  let started = false;

  function current() {
    return SHOTS[index];
  }

  return {
    get shot() {
      return current().name;
    },
    get changed() {
      const c = changed;
      changed = false;
      return c;
    },
    /** how far into the current shot we are (seconds) */
    get shotTime() {
      return shotTime;
    },
    get shotDuration() {
      return current().dur;
    },
    reset() {
      index = 0;
      shotTime = 0;
      started = false;
    },
    update(dt, rider) {
      const shot = current();
      shotTime += dt;
      if (shotTime > shot.dur) {
        shotTime = 0;
        index = (index + 1) % SHOTS.length;
        changed = true;
        started = true;
      }

      const s = rider.state;
      current().fn(rider, hold);

      // a hand-held wobble so the frame never feels locked off
      const t = performance.now() * 0.001;
      const wob = 0.07;
      dPos.copy(hold.pos);
      dPos.x += Math.sin(t * 0.9) * wob + Math.sin(t * 2.3) * wob * 0.4;
      dPos.y += Math.sin(t * 1.3 + 1.0) * wob * 0.7;
      dPos.z += Math.cos(t * 0.7) * wob;
      dTarget.copy(hold.target);

      if (!started) {
        pos.copy(dPos);
        target.copy(dTarget);
      } else {
        const k = 1 - Math.exp(-shot.smooth * dt);
        pos.lerp(dPos, k);
        target.lerp(dTarget, k);
      }

      // never let the lens dip under the surface
      const minY = waveFloor(rider, pos.x, pos.z) + 0.55;
      if (pos.y < minY) pos.y = minY;

      camera.position.copy(pos);
      blended.copy(up).lerp(s.up, 0.1).normalize();
      camera.up.copy(blended);
      camera.lookAt(target);

      const wantFov = shot.fov;
      if (!started || camera.fov === 0) camera.fov = wantFov;
      else camera.fov += (wantFov - camera.fov) * (1 - Math.exp(-2.0 * dt));
      camera.updateProjectionMatrix();
    },
  };
}

