// Dev tool: dumps the scene state at a given timeline position.
import puppeteer from 'puppeteer';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = path.resolve(import.meta.dirname, '..');
execFileSync('esbuild', ['main.js', '--bundle', '--format=esm', '--outfile=tools/preview/bundle.js'], { cwd: root, stdio: 'inherit' });

const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
const server = http.createServer((req, res) => {
  const file = path.join(root, req.url === '/' ? 'index.html' : req.url.split('?')[0]);
  if (!file.startsWith(root) || !fs.existsSync(file)) { res.writeHead(404).end('nope'); return; }
  res.writeHead(200, { 'content-type': types[path.extname(file)] || 'text/plain' });
  fs.createReadStream(file).pipe(res);
});
await new Promise((r) => server.listen(0, r));

const secs = process.argv.slice(2).map(Number);
const browser = await puppeteer.launch({ args: ['--no-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage();
await page.setViewport({ width: 960, height: 600 });
page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
await page.goto(`http://127.0.0.1:${server.address().port}/tools/preview/index.html`, { waitUntil: 'load' });
await page.waitForFunction('window.__pelican !== undefined', { timeout: 60000 });
await new Promise((r) => setTimeout(r, 1500));

const out = await page.evaluate((secs) => {
  const P = window.__pelican;
  const THREE = P.scene.constructor === undefined ? null : null;
  const res = [];
  for (const s of secs) {
    P.seek(s);
    const cam = P.rig && P.scene;
    const camera = null;
    // grab camera through the rig closure is not possible; use the dome parent
    let cameraObj = null;
    P.scene.traverse((o) => { if (o.isCamera) cameraObj = o; });
    const rider = P.rider;
    const st = rider.state;
    const cp = cameraObj.position;
    const rp = st.position;
    const dir = { x: cp.x - rp.x, y: cp.y - rp.y, z: cp.z - rp.z };
    const proj = cameraObj.worldToLocal(rp.clone());
    const ndc = proj.clone().applyMatrix4(cameraObj.projectionMatrix);
    res.push({
      t: s,
      shot: P.rig.shot,
      cam: [cp.x.toFixed(2), cp.y.toFixed(2), cp.z.toFixed(2)].join(','),
      rider: [rp.x.toFixed(2), rp.y.toFixed(2), rp.z.toFixed(2)].join(','),
      rel: [dir.x.toFixed(2), dir.y.toFixed(2), dir.z.toFixed(2)].join(','),
      ndc: [ndc.x.toFixed(2), ndc.y.toFixed(2), ndc.z.toFixed(3)].join(','),
      waves: window.__pelican.ocean.uniforms.uRider.value.toArray().map((v) => v.toFixed(1)).join(','),
    });
  }
  return res;
}, secs);

for (const r of out) console.log(JSON.stringify(r));
await browser.close();
server.close();

