// Dev tool: hides scene objects one at a time and reports one pixel, so the
// source of a visual can be identified.
import puppeteer from 'puppeteer';
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = path.resolve(import.meta.dirname, '..');
execFileSync('esbuild', ['main.js', '--bundle', '--format=esm', '--outfile=tools/preview/bundle.js'], { cwd: root, stdio: 'inherit' });

const types = { '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css' };
const server = http.createServer((req, res) => {
  const file = path.join(root, req.url === '/' ? 'index.html' : req.url.split('?')[0]);
  if (!file.startsWith(root) || !fs.existsSync(file)) { res.writeHead(404).end('nope'); return; }
  res.writeHead(200, { 'content-type': types[path.extname(file)] || 'text/plain' });
  fs.createReadStream(file).pipe(res);
});
await new Promise((r) => server.listen(0, r));

const browser = await puppeteer.launch({ args: ['--no-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader'] });
const page = await browser.newPage();
await page.setViewport({ width: 640, height: 400 });
page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
await page.goto(`http://127.0.0.1:${server.address().port}/tools/preview/index.html`, { waitUntil: 'load' });
await page.waitForFunction('window.__pelican !== undefined', { timeout: 60000 });
await new Promise((r) => setTimeout(r, 1200));

const px = Number(process.argv[3] || 0.75);
const py = Number(process.argv[4] || 0.7);
const sec = Number(process.argv[2] || 31);

const result = await page.evaluate(
  async (sec, px, py) => {
    const P = window.__pelican;
    const scene = P.scene;
    const byName = {};
    scene.traverse((o) => {
      if (o.name) byName[o.name] = byName[o.name] || o;
    });
    const names = [
      'ocean', 'islands', 'flock', 'rider', 'board', 'pelican', 'head', 'wingL',
      'spray', 'shadow', 'dome', 'sky',
    ].filter((n) => byName[n]);
    const readPixel = () => {
      const c = document.getElementById('scene');
      const o = document.createElement('canvas');
      o.width = c.width;
      o.height = c.height;
      const ctx = o.getContext('2d');
      ctx.drawImage(c, 0, 0);
      const x = Math.floor(px * o.width);
      const y = Math.floor(py * o.height);
      const d = ctx.getImageData(x, y, 1, 1).data;
      return [d[0], d[1], d[2]].join(',');
    };
    const out = {};
    P.seek(sec);
    out.baseline = readPixel();
    for (const n of names) {
      const o = byName[n];
      const vis = o.visible;
      o.visible = false;
      P.seek(sec);
      out['-' + n] = readPixel();
      o.visible = vis;
    }
    // also: what meshes are actually visible at all?
    out.list = scene.children.map((c) => `${c.name || c.type}:${c.children.length}`);
    return out;
  },
  sec,
  px,
  py,
);

console.log(`t=${sec} pixel(${px},${py})`);
for (const [k, v] of Object.entries(result)) console.log(k.padEnd(12), v);
await browser.close();
server.close();

